CREATE OR REPLACE FUNCTION public.apply_rider_morale_event(p_rider_id uuid, p_season_day_id uuid, p_source_type text, p_source_reference text, p_requested_delta numeric, p_description text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_day record;
  v_existing public.rider_morale_events%rowtype;
  v_previous_condition record;
  v_condition public.rider_condition_states%rowtype;
  v_before numeric(5, 2);
  v_after numeric(5, 2);
  v_applied numeric(5, 2);
begin
  if p_rider_id is null or p_season_day_id is null then
    raise exception 'Le coureur et la journée sont requis pour modifier le moral.';
  end if;
  if p_source_type not in (
    'social_integration', 'team_tenure', 'stage_result', 'race_result',
    'favorite_race', 'injury', 'training_overload', 'mixed_zone_interview',
    'academy_promotion', 'manual_adjustment', 'race_load'
  ) then
    raise exception 'Cette source de moral n’est pas autorisée.';
  end if;
  if btrim(coalesce(p_source_reference, '')) = ''
    or btrim(coalesce(p_description, '')) = '' then
    raise exception 'La variation de moral doit être traçable et expliquée.';
  end if;
  if p_requested_delta is null
    or p_requested_delta = 0
    or p_requested_delta not between -100 and 100 then
    raise exception 'La variation de moral doit être comprise entre −100 et +100.';
  end if;
  if coalesce(jsonb_typeof(p_metadata), 'null') <> 'object' then
    raise exception 'Les métadonnées de moral doivent former un objet.';
  end if;

  -- Serialize every rider independently. This also makes trigger retries safe.
  perform pg_advisory_xact_lock(hashtextextended(p_rider_id::text, 0));

  select * into v_existing
  from public.rider_morale_events as event
  where event.rider_id = p_rider_id
    and event.source_type = p_source_type
    and event.source_reference = p_source_reference;
  if v_existing.id is not null then
    return jsonb_build_object(
      'alreadyApplied', true,
      'eventId', v_existing.id,
      'moraleBefore', v_existing.morale_before,
      'moraleAfter', v_existing.morale_after,
      'appliedDelta', v_existing.applied_delta
    );
  end if;

  select day.id, day.season_id, day.day_number
  into v_day
  from public.season_days as day
  where day.id = p_season_day_id;
  if v_day.id is null then
    raise exception 'La journée de saison du moral est introuvable.';
  end if;

  select
    state.form,
    state.fatigue,
    state.morale
  into v_previous_condition
  from public.rider_condition_states as state
  join public.season_days as state_day on state_day.id = state.season_day_id
  where state.rider_id = p_rider_id
    and state_day.season_id = v_day.season_id
    and state_day.day_number <= v_day.day_number
  order by state_day.day_number desc, state.updated_at desc
  limit 1;

  insert into public.rider_condition_states (
    rider_id, season_day_id, form, fatigue, morale, source
  ) values (
    p_rider_id,
    p_season_day_id,
    coalesce(v_previous_condition.form, 75),
    coalesce(v_previous_condition.fatigue, 0),
    coalesce(v_previous_condition.morale, 60),
    'morale:' || p_source_type
  )
  on conflict (rider_id, season_day_id) do nothing;

  select * into v_condition
  from public.rider_condition_states as state
  where state.rider_id = p_rider_id
    and state.season_day_id = p_season_day_id
  for update;

  v_before := coalesce(v_condition.morale, 60);
  v_after := least(100, greatest(0, v_before + p_requested_delta));
  v_applied := v_after - v_before;

  update public.rider_condition_states
  set
    morale = v_after,
    updated_at = now()
  where id = v_condition.id;

  insert into public.rider_morale_events (
    rider_id, season_day_id, source_type, source_reference,
    requested_delta, applied_delta, morale_before, morale_after,
    description, metadata
  ) values (
    p_rider_id, p_season_day_id, p_source_type, p_source_reference,
    p_requested_delta, v_applied, v_before, v_after,
    btrim(p_description), coalesce(p_metadata, '{}'::jsonb)
  )
  returning id into v_existing.id;

  return jsonb_build_object(
    'alreadyApplied', false,
    'eventId', v_existing.id,
    'moraleBefore', v_before,
    'moraleAfter', v_after,
    'appliedDelta', v_applied
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_youth_rider_morale_event(p_academy_rider_id uuid, p_season_day_id uuid, p_source_type text, p_source_reference text, p_requested_delta numeric, p_description text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_existing public.youth_rider_morale_events%rowtype;
  v_before numeric(5, 2);
  v_after numeric(5, 2);
  v_applied numeric(5, 2);
begin
  if p_academy_rider_id is null then
    raise exception 'Le junior est requis pour modifier son moral.';
  end if;
  if p_source_type not in (
    'social_integration', 'development_result', 'manual_adjustment'
  ) then
    raise exception 'Cette source de moral junior n’est pas autorisée.';
  end if;
  if btrim(coalesce(p_source_reference, '')) = ''
    or btrim(coalesce(p_description, '')) = '' then
    raise exception 'La variation de moral junior doit être traçable et expliquée.';
  end if;
  if p_requested_delta is null
    or p_requested_delta = 0
    or p_requested_delta not between -100 and 100 then
    raise exception 'La variation de moral junior doit être comprise entre −100 et +100.';
  end if;
  if coalesce(jsonb_typeof(p_metadata), 'null') <> 'object' then
    raise exception 'Les métadonnées de moral junior doivent former un objet.';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_academy_rider_id::text, 1));

  select * into v_existing
  from public.youth_rider_morale_events as event
  where event.academy_rider_id = p_academy_rider_id
    and event.source_type = p_source_type
    and event.source_reference = p_source_reference;
  if v_existing.id is not null then
    return jsonb_build_object(
      'alreadyApplied', true,
      'eventId', v_existing.id,
      'moraleBefore', v_existing.morale_before,
      'moraleAfter', v_existing.morale_after,
      'appliedDelta', v_existing.applied_delta
    );
  end if;

  select morale into v_before
  from public.youth_academy_riders
  where id = p_academy_rider_id
  for update;
  if not found then raise exception 'Le junior est introuvable.'; end if;

  v_before := coalesce(v_before, 60);
  v_after := least(100, greatest(0, v_before + p_requested_delta));
  v_applied := v_after - v_before;

  update public.youth_academy_riders
  set morale = v_after, updated_at = now()
  where id = p_academy_rider_id;

  insert into public.youth_rider_morale_events (
    academy_rider_id, season_day_id, source_type, source_reference,
    requested_delta, applied_delta, morale_before, morale_after,
    description, metadata
  ) values (
    p_academy_rider_id, p_season_day_id, p_source_type, p_source_reference,
    p_requested_delta, v_applied, v_before, v_after,
    btrim(p_description), coalesce(p_metadata, '{}'::jsonb)
  )
  returning id into v_existing.id;

  return jsonb_build_object(
    'alreadyApplied', false,
    'eventId', v_existing.id,
    'moraleBefore', v_before,
    'moraleAfter', v_after,
    'appliedDelta', v_applied
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_federation_callup_ineligibility_reason(p_member_id uuid, p_departure_at timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_member record;
begin
  select member.*, selection_list.country_id, selection_list.season_id,
    season.game_year, season.status as season_status,
    slot.rider_category, slot.competition_code, slot.slot_key,
    coalesce(pro.status, junior.status) as rider_status,
    coalesce(pro.country_id, junior.country_id) as rider_country_id,
    junior.team_id as junior_team_id, junior.birth_game_year
  into v_member
  from public.national_federation_selection_members member
  join public.national_federation_selection_lists selection_list on selection_list.id=member.selection_list_id
  join public.seasons season on season.id=selection_list.season_id
  join public.national_federation_selection_slots slot on slot.slot_key=selection_list.slot_key
  left join public.riders pro on pro.id=member.professional_rider_id
  left join public.youth_academy_riders junior on junior.id=member.junior_rider_id
  where member.id=p_member_id;
  if not found then return 'missing_rider'; end if;
  if v_member.season_status <> 'active'
     or not public.federation_selection_slot_is_available(v_member.slot_key,v_member.game_year)
  then return 'inactive_competition'; end if;
  if v_member.rider_country_id is distinct from v_member.country_id then return 'nationality_changed'; end if;
  if v_member.professional_rider_id is not null then
    if v_member.rider_category <> 'professional'
       or v_member.rider_status is null or v_member.rider_status not in ('active','free_agent')
    then return 'rider_inactive'; end if;
    if v_member.owner_team_id is not null and not exists (
      select 1 from public.rider_contracts contract
      join public.teams team on team.id=contract.team_id and team.status='active'
      where contract.rider_id=v_member.professional_rider_id
        and contract.team_id=v_member.owner_team_id and contract.status='active'
    ) then return 'ownership_changed'; end if;
    if exists (
      select 1 from public.rider_injuries injury
      where injury.rider_id=v_member.professional_rider_id and injury.status='active'
        and (p_departure_at is null or (injury.started_at < p_departure_at and injury.expected_recovery_at > p_departure_at))
    ) then return 'injury'; end if;
    if v_member.competition_code='nations_cup'
       and coalesce(public.get_federation_selection_rider_limit(v_member.country_id,v_member.season_id,v_member.slot_key),0)=0
    then return 'nation_unqualified'; end if;
    if v_member.competition_code in ('continental_championship','world_championship') and not exists (
      select 1 from public.international_nation_qualification_snapshots qualification
      where qualification.season_id=v_member.season_id and qualification.country_id=v_member.country_id
        and qualification.competition_code=v_member.competition_code and qualification.is_qualified
    ) then return 'nation_unqualified'; end if;
  else
    if v_member.rider_category <> 'junior'
       or v_member.rider_status is null or v_member.rider_status not in ('active','recruited')
    then return 'rider_inactive'; end if;
    if v_member.game_year-v_member.birth_game_year not between 16 and 18 then return 'junior_age'; end if;
    if v_member.junior_team_id is distinct from v_member.owner_team_id then return 'ownership_changed'; end if;
  end if;
  if v_member.owner_director_id is not null and not exists (
    select 1 from public.team_manager_assignments assignment
    join public.sporting_directors director on director.id=assignment.sporting_director_id and director.status='active'
    join public.teams team on team.id=assignment.team_id and team.status='active'
    where assignment.team_id=v_member.owner_team_id and assignment.sporting_director_id=v_member.owner_director_id
      and assignment.role='general_manager' and assignment.status='active'
  ) then return 'ownership_changed'; end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.invalidate_ineligible_federation_callups(p_selection_list_id uuid, p_departure_at timestamp with time zone)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_count integer;
begin
  if p_departure_at is null or p_departure_at <= now() then return 0; end if;
  perform 1 from public.national_federation_selection_lists where id=p_selection_list_id for update;
  update public.national_federation_selection_members member
  set response_status='ineligible',responded_at=now()
  where member.selection_list_id=p_selection_list_id and member.response_status in ('pending','confirmed')
    and public.get_federation_callup_ineligibility_reason(member.id,p_departure_at) is not null;
  get diagnostics v_count=row_count;
  if v_count>0 then
    update public.national_federation_selection_lists selection_list
    set updated_at=now(),status=case when selection_list.status='draft' then 'draft' when exists (
      select 1 from public.national_federation_selection_members member
      where member.selection_list_id=selection_list.id and member.response_status='pending'
    ) then 'pending_confirmation' else 'finalized' end
    where selection_list.id=p_selection_list_id;
  end if;
  return v_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.respond_to_international_championship_selection(p_candidate_id uuid, p_accept boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_director_id uuid;
  v_candidate public.international_championship_rider_selections%rowtype;
  v_race_edition_id uuid;
  v_departure_at timestamptz;
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('international-championship-selections', 0)
  );

  if p_accept is null then
    raise exception 'La décision de sélection est invalide.';
  end if;

  select director.id
  into v_director_id
  from public.sporting_directors as director
  where director.auth_user_id = auth.uid()
    and director.status = 'active';

  if v_director_id is null then
    raise exception using
      errcode = '42501',
      message = 'Aucun Directeur Sportif actif n''est associé à ce compte.';
  end if;

  select candidate.*
  into v_candidate
  from public.international_championship_rider_selections as candidate
  where candidate.id = p_candidate_id
  for update;

  if not found
    or v_candidate.sporting_director_id is distinct from v_director_id
  then
    raise exception using
      errcode = '42501',
      message = 'Vous ne pouvez pas répondre pour ce coureur.';
  end if;

  select selection.race_edition_id, min(stage.departure_at)
  into v_race_edition_id, v_departure_at
  from public.international_championship_nation_selections as selection
  join public.stages as stage
    on stage.race_edition_id = selection.race_edition_id
  where selection.id = v_candidate.nation_selection_id
  group by selection.race_edition_id;

  if v_candidate.response_status <> 'pending'
    or v_candidate.is_selected = false
  then
    raise exception
      'Une décision définitive a déjà été enregistrée pour ce coureur.';
  end if;

  if v_departure_at is null or now() >= v_departure_at then
    raise exception
      'Le départ est donné : la sélection est désormais définitive.';
  end if;

  if p_accept and public.is_rider_protected_by_stage_race_for_international_selection(
    v_candidate.rider_id,
    v_race_edition_id,
    now()
  ) then
    update public.international_championship_rider_selections
    set response_status = 'unavailable', is_selected = false, responded_at = now()
    where id = v_candidate.id;

    delete from public.sporting_director_messages
    where sporting_director_id = v_director_id
      and source_reference = 'international-selection:' || v_candidate.id::text;

    perform public.sync_international_championship_lineup(
      v_candidate.nation_selection_id
    );
    return;
  end if;

  if p_accept then
    update public.international_championship_rider_selections
    set response_status = 'confirmed', responded_at = now()
    where id = v_candidate.id;

    perform public.sync_international_championship_lineup(
      v_candidate.nation_selection_id
    );
  else
    update public.international_championship_rider_selections
    set response_status = 'declined', is_selected = false, responded_at = now()
    where id = v_candidate.id;

    perform public.sync_international_championship_lineup(
      v_candidate.nation_selection_id
    );
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.respond_to_international_selections_with_conflict_ack(p_decisions jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_decision jsonb;
  v_candidate_id uuid;
  v_decision_count integer;
  v_eligible_count integer;
  v_acknowledged_conflicts text[];
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('international-championship-selections', 0)
  );

  if p_decisions is null or jsonb_typeof(p_decisions) <> 'array' then
    raise exception 'Le lot de décisions est invalide.';
  end if;

  v_decision_count := jsonb_array_length(p_decisions);

  if v_decision_count < 1 or v_decision_count > 100 then
    raise exception 'Le lot doit contenir entre 1 et 100 décisions.';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_decisions) as decision(value)
    where jsonb_typeof(decision.value) <> 'object'
      or coalesce(decision.value ->> 'candidateId', '')
        !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or jsonb_typeof(decision.value -> 'accept') <> 'boolean'
      or jsonb_typeof(decision.value -> 'acknowledgedConflicts') <> 'array'
      or jsonb_array_length(decision.value -> 'acknowledgedConflicts') > 40
      or exists (
        select 1
        from jsonb_array_elements(
          decision.value -> 'acknowledgedConflicts'
        ) as conflict(value)
        where jsonb_typeof(conflict.value) <> 'string'
          or length(conflict.value #>> '{}') < 1
          or length(conflict.value #>> '{}') > 300
      )
  ) then
    raise exception 'Une décision du lot est invalide.';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_decisions) as decision(value)
    group by decision.value ->> 'candidateId'
    having count(*) > 1
  ) then
    raise exception 'Une convocation ne peut apparaître qu’une fois dans le lot.';
  end if;

  select count(distinct candidate.id)::integer
  into v_eligible_count
  from jsonb_array_elements(p_decisions) as decision(value)
  join public.international_championship_rider_selections as candidate
    on candidate.id = (decision.value ->> 'candidateId')::uuid
   and candidate.response_status = 'pending'
   and candidate.is_selected = true
  join public.sporting_directors as director
    on director.id = candidate.sporting_director_id
   and director.auth_user_id = auth.uid()
   and director.status = 'active';

  if v_eligible_count <> v_decision_count then
    raise exception using
      errcode = '42501',
      message = 'Une convocation a changé ou ne vous appartient pas. Rechargez la page avant de confirmer le lot.';
  end if;

  for v_decision in
    select decision.value
    from jsonb_array_elements(p_decisions) as decision(value)
    order by decision.value ->> 'candidateId'
  loop
    v_candidate_id := (v_decision ->> 'candidateId')::uuid;

    select coalesce(
      array_agg(conflict.value order by conflict.ordinality),
      array[]::text[]
    )
    into v_acknowledged_conflicts
    from jsonb_array_elements_text(
      v_decision -> 'acknowledgedConflicts'
    ) with ordinality as conflict(value, ordinality);

    perform public.respond_to_international_selection_with_conflict_ack(
      v_candidate_id,
      (v_decision ->> 'accept')::boolean,
      v_acknowledged_conflicts
    );
  end loop;

  return v_decision_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.respond_to_national_federation_preselection(p_member_id uuid, p_accept boolean)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '10s'
AS $function$
declare
  v_identity record;
  v_season public.seasons%rowtype;
  v_member public.national_federation_selection_members%rowtype;
  v_list public.national_federation_selection_lists%rowtype;
  v_slot public.national_federation_selection_slots%rowtype;
  v_country_code text;
  v_rider_name text;
  v_president_id uuid;
  v_callup_departure timestamptz;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentification requise.';
  end if;

  -- Lock parent first: a simultaneous save cannot delete a newly accepted rider.
  select selection_list.* into v_list
  from public.national_federation_selection_lists as selection_list
  join public.national_federation_selection_members as member on member.selection_list_id = selection_list.id
  where member.id = p_member_id for update of selection_list;
  select * into v_member from public.national_federation_selection_members
  where id = p_member_id for update;
  select country.iso_alpha2 into v_country_code
  from public.countries as country
  where country.id = v_list.country_id;
  -- A Belgian DS must also be able to answer for a French rider, for example.
  select director.id as sporting_director_id, team.id as team_id,
    coalesce(team.amateur_name, team.internal_name) as team_name into v_identity
  from public.sporting_directors as director
  join public.team_manager_assignments as assignment on assignment.sporting_director_id = director.id
    and assignment.role = 'general_manager' and assignment.status = 'active'
  join public.teams as team on team.id = assignment.team_id and team.status = 'active'
  where director.auth_user_id = (select auth.uid()) and director.status = 'active'
    and director.id = v_member.owner_director_id and team.id = v_member.owner_team_id
  limit 1;
  select * into v_season
  from public.seasons
  where status = 'active'
  limit 1;
  select * into v_slot
  from public.national_federation_selection_slots
  where slot_key = v_list.slot_key;

  if v_member.id is null
     or v_identity.team_id is null
     or v_member.owner_team_id <> v_identity.team_id
     or v_member.owner_director_id is distinct from v_identity.sporting_director_id then
    raise exception 'Cette demande ne concerne pas votre équipe.';
  end if;
  if v_member.response_status = 'ineligible' then return 'ineligible'; end if;
  if v_member.response_status <> 'pending' then
    raise exception 'Cette demande a déjà été traitée.';
  end if;

  perform public.assert_federation_callup_response_open(v_list.country_id, v_list.season_id, v_list.slot_key);
  if p_accept is null then raise exception 'Décision invalide.'; end if;
  -- callup_eligibility_v1: an invalidation is committed, not rolled back by an exception.
  select schedule.departure_at into v_callup_departure
  from public.get_national_federation_selection_schedule(v_list.country_id,v_list.season_id) schedule
  where schedule.slot_key=v_list.slot_key;
  if public.get_federation_callup_ineligibility_reason(v_member.id,v_callup_departure) is not null then
    perform public.invalidate_ineligible_federation_callups(v_list.id,v_callup_departure);
    if v_member.professional_rider_id is not null then
      perform public.refill_national_federation_professional_selection(v_list.id,now());
      perform public.sync_national_federation_championship_lineup(v_list.id);
    else
      perform public.sync_national_federation_junior_lineup(v_list.id);
    end if;
    return 'ineligible';
  end if;
  if p_accept and v_member.professional_rider_id is not null and not exists (
    select 1 from public.rider_contracts as contract
    where contract.rider_id = v_member.professional_rider_id
      and contract.team_id = v_identity.team_id and contract.status = 'active'
  ) then raise exception 'Ce coureur ne fait plus partie de votre équipe.'; end if;
  if p_accept and v_member.junior_rider_id is not null and not exists (
    select 1 from public.youth_academy_riders as rider
    where rider.id = v_member.junior_rider_id and rider.team_id = v_identity.team_id
      and rider.status in ('active', 'recruited')
      and v_season.game_year - rider.birth_game_year between 16 and 18
  ) then raise exception 'Ce junior ne fait plus partie des coureurs éligibles de votre équipe.'; end if;

  -- s5_championship_quotas: never confirm beyond the frozen national quota.
  if p_accept and v_season.game_year >= 5 and v_slot.rider_category='professional'
    and v_slot.competition_code in ('world_championship','continental_championship')
    and (select count(*) from public.national_federation_selection_members
      where selection_list_id=v_list.id and response_status='confirmed')
      >= coalesce(public.get_federation_selection_rider_limit(v_list.country_id,v_list.season_id,v_list.slot_key),0) then
    raise exception 'Le quota de cette épreuve est atteint.';
  end if;
  update public.national_federation_selection_members
  set
    response_status = case when p_accept then 'confirmed' else 'declined' end,
    responded_at = now()
  where id = v_member.id;

  select coalesce(
    (
      select rider.first_name || ' ' || rider.last_name
      from public.riders as rider
      where rider.id = v_member.professional_rider_id
    ),
    (
      select rider.first_name || ' ' || rider.last_name
      from public.youth_academy_riders as rider
      where rider.id = v_member.junior_rider_id
    ),
    'Le coureur'
  ) into v_rider_name;

  select term.president_director_id into v_president_id
  from public.national_federation_terms as term
  where term.country_id = v_list.country_id
    and term.start_game_year <= v_season.game_year
    and term.end_game_year >= v_season.game_year
  limit 1;

  if v_president_id is not null
     and v_president_id <> v_identity.sporting_director_id then
    insert into public.sporting_director_messages (
      sporting_director_id, season_id, message_type, sender_name, subject,
      preview, body, action_href, action_label, source_reference, is_important
    ) values (
      v_president_id, v_season.id, 'international_selection',
      v_identity.team_name,
      case when p_accept then 'Présélection confirmée' else 'Présélection refusée' end,
      v_rider_name || case when p_accept then ' sera disponible.' else ' ne sera pas disponible.' end,
      case when p_accept
        then 'La participation du coureur est confirmée par son DS.'
        else 'La liste doit être revue ou un remplaçant doit être appelé.' end,
      '/jeu/federations/' || lower(v_country_code) || '?onglet=selections',
      'Voir la sélection',
      'federation-selection:' || v_member.id::text || ':response',
      not p_accept
    ) on conflict (sporting_director_id, source_reference) do nothing;
  end if;

  insert into public.national_federation_journal_entries (
    country_id, season_id, day_number, category, title, detail, source_reference
  ) values (
    v_list.country_id, v_season.id, v_season.current_day_number, 'selection',
    case when p_accept then 'Disponibilité confirmée' else 'Disponibilité refusée' end,
    v_identity.team_name || ' · ' || v_rider_name || ' · ' || public.federation_selection_slot_label(v_slot.slot_key, v_slot.label, v_season.game_year) || '.',
    'federation-selection:' || v_member.id::text || ':response'
  ) on conflict (source_reference) do nothing;

  if not exists (
    select 1
    from public.national_federation_selection_members
    where selection_list_id = v_list.id
      and response_status = 'pending'
  ) then
    update public.national_federation_selection_lists
    set status = 'finalized', updated_at = now()
    where id = v_list.id;
  end if;


  if not p_accept and v_member.professional_rider_id is not null then
    perform public.refill_national_federation_professional_selection(
      v_list.id, now()
    );
  end if;

  perform public.sync_national_federation_championship_lineup(v_list.id);
  if p_accept and v_member.professional_rider_id is not null and not exists (
    select 1 from public.national_federation_selection_race_links as link
    join public.race_rosters as roster on roster.race_registration_id = link.race_registration_id
    where link.selection_list_id = v_list.id and roster.rider_id = v_member.professional_rider_id
      and roster.status in ('selected', 'confirmed')
  ) then
    raise exception 'La participation ne peut pas être confirmée : le coureur est indisponible pour cette épreuve (tour verrouillé ou commencé notamment).';
  end if;
  return case when p_accept then 'confirmed' else 'declined' end;
end;
